    'getPoolBalances' : IDL.Func([], [PoolBalances], []),
    'getPrizePoolBalance' : IDL.Func([PrizePoolId], [IDL.Nat], ['query']),
    'getSwapQuote' : IDL.Func([SwapDirection, IDL.Nat], [SwapQuote], ['query']),
    'getTreasuryBalance' : IDL.Func([], [IDL.Nat], ['query']),
    'getTreasuryPrincipal' : IDL.Func([], [IDL.Principal], ['query']),
    'getWalletBalances' : IDL.Func([], [WalletBalances], []),
    'icrc1_balance_of' : IDL.Func([Account], [IDL.Nat], ['query']),
